 "title": "PE question 3 with streams — that still compiles on JDK 8",
 "src": "src",
 "extra": [],
 "main": "Main",
 "javaMin": 8,
 "timeoutMs": 10000,
 "loose": false,
 "lab211": false,
 "rules": [],
 "cases": [
  {
   "name": "five books, two Java titles, two at the top price",
   "input": "Head First Java;12.5\nClean Code;30\nJava Puzzlers;8.25\nSQL;30\nC Book;4\n",
   "expected": "f1 = 10.38\nf2 = [SQL(30.0), C Book(4.0), Clean Code(30.0), Java Puzzlers(8.25), Head First Java(12.5)]\nf3 = [Head First Java(12.5), Java Puzzlers(8.25), C Book(4.0)]\n"
  },
  {
   "h": ""
  },
  {
   "h": "eyJuYW1lIjoiZW1wdHkgbGlzdCIsImlucHV0IjoiXG4iLCJleHBlY3RlZCI6ImYxID0gMC4wMFxuZjIgPSBbXVxuZjMgPSBbXVxuIn0="
